use "dice";

fn normal::(mean, stddev) {
    let u1 = @rand();
    let u2 = @rand();
    if (u1 < 0.0000001) { u1 = 0.0000001; }
    let z = @sqrt(-2.0 * @log(u1)) * @cos(6.28318530718 * u2);
    return mean + z * stddev;
}

fn exponential::(lambda) {
    let u = @rand();
    if (u < 0.0000001) { u = 0.0000001; }
    return -@log(u) / lambda;
}

fn poisson::(lambda) {
    let L = @exp(-lambda);
    let k = 0;
    let p = 1.0;
    while (true) {
        k = k + 1;
        p = p * @rand();
        if (p <= L) { break; }
    }
    return k - 1;
}

fn bernoulli::(p) {
    return @rand() < p;
}

fn binomial::(n, p) {
    let s = 0;
    let i = 0;
    while (i < n) {
        if (bernoulli(p)) { s = s + 1; }
        i = i + 1;
    }
    return s;
}

fn rand_range::(lo, hi) {
    return lo + @rand() * (hi - lo);
}

fn rand_int_excl::(lo, hi) {
    return @rand_int(lo, hi - 1);
}

fn sample_no_repeat::(population, k) {
    if (k > @len(population)) {
        @throw "sample: k > population size";
    }
    let copy = population;
    dice.shuffle(copy);
    let out = [];
    let i = 0;
    while (i < k) {
        @push(out, copy[i]);
        i = i + 1;
    }
    return out;
}

fn random_bytes::(n) {
    let out = [];
    let i = 0;
    while (i < n) {
        @push(out, @rand_int(0, 255));
        i = i + 1;
    }
    return out;
}

fn uuid::() {
    return @uuid();
}

fn password::(length) {
    let abc = "abcdefghijklmnopqrstuvwxyz";
    let ABC = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let num = "0123456789";
    let sym = "!@#$%^&*()-_=+";
    let pool = abc + ABC + num + sym;
    let out = "";
    let i = 0;
    while (i < length) {
        let idx = @rand_int(0, @len(pool) - 1);
        out = out + @substr(pool, idx, 1);
        i = i + 1;
    }
    return out;
}

fn lottery::(total, winners) {
    let pool = [];
    let i = 1;
    while (i <= total) {
        @push(pool, i);
        i = i + 1;
    }
    return sample_no_repeat(pool, winners);
}
